#[test]
fn meta_filter_matches_yaml_list_value_in_bare_frontmatter() {
    setup();

    // Regression: `wrap_bare_frontmatter` previously dropped lines starting
    // with whitespace, which silently discarded indented YAML list items.
    // A `depends:` field with `- foo` underneath then became an empty value
    // and `iwe find --meta depends=foo` returned no results.
    let graph = Graph::import(
        &from_indoc(indoc! {"
            title: Foo
            depends:
              - foo
              - bar

            # Body
            "}),
        bare_options(),
        None,
    );

    let finder = liwe::find::DocumentFinder::new(&graph);
    let options = liwe::find::FindOptions {
        metadata_filters: vec![("depends".to_string(), "foo".to_string())],
        ..Default::default()
    };
    let output = finder.find(&options);
    assert_eq!(output.results.len(), 1);
    assert_eq!(output.results[0].title, "Foo");
}
